// coreboot.bin file used in this test is generated by create_coreboot_bin.sh script

func TestCBFSGetFiles(t *testing.T) {
	data, err := ioutil.ReadFile("coreboot.bin")
	if err != nil {
		t.Fatal(err)
	}

	files, err := CBFSGetFiles(data)
	if err != nil {
		t.Fatal(err)
	}

	for i, s := range []struct {
		fileType CBFSFileType
		name     string
	}{
		{CBFSFileTypeRaw, "fmap_src"},
		{CBFSFileTypeRaw, "int_file"},
		{CBFSFileTypeRaw, "int_file_2"},
		{CBFSFileTypeRaw, "fmap_src_lzma"},
	} {
		if files[i].FileType != s.fileType || files[i].Filename != s.name {
			t.Log("Mismatch: ", files[i], ", ", s, "")
			t.Fatalf("CBFS files do not match expected")
		}
	}
}

