func TestCBFSGetFile(t *testing.T) {
	data, err := ioutil.ReadFile("coreboot.bin")
	if err != nil {
		t.Fatal(err)
	}

	for _, s := range []struct {
		fileType CBFSFileType
		name     string
	}{
		{CBFSFileTypeRaw, "fmap_src"},
		{CBFSFileTypeRaw, "int_file"},
		{CBFSFileTypeRaw, "int_file_2"},
		{CBFSFileTypeRaw, "fmap_src_lzma"},
	} {
		file, err := CBFSGetFile(data, s.name)
		if err != nil {
			t.Fatal(err)
		}
		if file.FileType != s.fileType || file.Filename != s.name {
			t.Log("Mismatch: ", file, ", ", s, "")
			t.Fatalf("CBFS files do not match expected")
		}
	}

	file, err := CBFSGetFile(data, "")
	if file != nil || err != nil {
		t.Fatalf("Unexpectedly found empty file")
	}
}

func TestCBFSGetFileCompressionAttribute(t *testing.T) {
	data, err := ioutil.ReadFile("coreboot.bin")
	if err != nil {
		t.Fatal(err)
	}

	file, err := CBFSGetFile(data, "fmap_src_lzma")
	if file == nil {
		t.Logf("File not found but expected")
		t.Fatal(err)
	}

	if len(file.Attributes) == 0 {
		t.Fatalf("Invalid number of file attributes")
	}

	attribute, ok := func() (CBFSFileAttributeCompression, bool) {
		for _, a := range file.Attributes {
			if a.GetTag() == CBFSFileAttributeTagCompression {
				return a.(CBFSFileAttributeCompression), true
			}
		}
		return CBFSFileAttributeCompression{}, false
	}()

	if !ok {
		t.Fatalf("Compression attribute not found, but expected")
	}

	if attribute.Compression != CBFSFileCompressionLZMA {
		t.Fatalf("LZMA compression expected")
	}
}

func TestCBFSWalkerCorrupt(t *testing.T) {
	data, err := ioutil.ReadFile("coreboot.bin")
	if err != nil {
		t.Fatal(err)
	}

	corruptorWalker := func(ctx CBFSWalkerContext) bool {
		if ctx.File.Filename == "fmap_src_lzma" {
			for i, v := range ctx.Buffer[:8] {
				ctx.Buffer[i] = (v + 1)
			}
			return true
		}
		return false
	}

	if err = CBFSWalk(data, corruptorWalker); err != nil {
		t.Fatal(err)
	}

	file, err := CBFSGetFile(data, "fmap_src_lzma")
	if !(file == nil && err == nil) {
		t.Fatalf("CBFS corruption was not successful. File found but not expected")
	}

	files, err := CBFSGetAllFiles(data)
	if err != nil {
		t.Fatal(err)
	}

	for i, s := range []struct {
		fileType CBFSFileType
		name     string
	}{
		{CBFSFileTypeRaw, "fmap_src"},
		{CBFSFileTypeRaw, "int_file"},
		{CBFSFileTypeRaw, "int_file_2"},
		{CBFSFileTypeNull, ""},
	} {
		if files[i].FileType != s.fileType || files[i].Filename != s.name {
			t.Log("Mismatch: ", files[i], ", ", s, "")
			t.Fatalf("CBFS files do not match expected")
		}
	}
}

func TestCBFSWalkerOverlapFile(t *testing.T) {
	data, err := ioutil.ReadFile("coreboot.bin")
	if err != nil {
		t.Fatal(err)
	}

	fmapSrcLzmaMagicCorruptorWalker := func(ctx CBFSWalkerContext) bool {
		if ctx.File.Filename == "fmap_src" {
			buf := new(bytes.Buffer)

			header := ctx.File.Header
			header.Len += CBFSFileHeaderSize * 2

			binary.Write(buf, binary.BigEndian, header)

			copy(ctx.Buffer, buf.Bytes())

			return true
		}
		return false
	}

	if err = CBFSWalk(data, fmapSrcLzmaMagicCorruptorWalker); err != nil {
		t.Fatal(err)
	}

	file, err := CBFSGetFile(data, "int_file")
	if !(file == nil && err == nil) {
		t.Fatalf("CBFS corruption was not successful. File found but not expected")
	}

	files, err := CBFSGetAllFiles(data)
	if err != nil {
		t.Fatal(err)
	}

	for i, s := range []struct {
		fileType CBFSFileType
		name     string
	}{
		{CBFSFileTypeRaw, "fmap_src"},
		{CBFSFileTypeRaw, "int_file_2"},
		{CBFSFileTypeRaw, "fmap_src_lzma"},
		{CBFSFileTypeNull, ""},
	} {
		if files[i].FileType != s.fileType || files[i].Filename != s.name {
			t.Log("Mismatch: ", files[i], ", ", s, "")
			t.Fatalf("CBFS files do not match expected")
		}
	}
}
